2	/**
3	 * Plugin Name: ARBE FP Guardrail Shortcode
4	 * Description: Adds the [arbe_fp_guardrail] shortcode for atlas-only FP string parsing.
5	 * Version: 1.0.1
6	 * Author: ARBE λ*
7	 */
8	
9	if (!defined('ABSPATH')) {
10	    exit;
11	}
12	
13	function arbe_fp_guardrail_shortcode() {
14	    ob_start();
15	    ?>
16	    <section class="arbe-fp-guardrail-widget" aria-labelledby="arbe-fp-guardrail-title">
17	      <h2 id="arbe-fp-guardrail-title">FP-Code Guardrail Check</h2>
18	      <p>Paste an ARBE FP string. The widget returns atlas-bound fields and keeps unknown fields raw / unverified.</p>
19	      <textarea id="arbe-fp-input" rows="5" style="width:100%;">FP1|ID=H235_L010_C005|ST=SCISSOR|A=H230_L010_C005|SOL=SS03-A100-E0002|MS=S:P,C:A|CLS=DA|SIG=S_60C98EE54AB6</textarea>
20	      <p><button id="arbe-fp-run" type="button">Validate FP string</button></p>
21	      <pre id="arbe-fp-output" aria-live="polite"></pre>
22	    </section>
23	    <script>
24	    window.ARBE_FP_GUARDRAIL = (function () {
25	      const REF_RE = /^H\d{3}_L\d{3}_C\d{3}$/;
26	      const ALLOWED_OPERATORS = {
27	        "SCISSOR": "ARBE Spectral Scissor"
28	      };
29	      const FORBIDDEN_INTERPRETATIONS = [
30	        "warehouse coordinate",
31	        "SAP logistics command",
32	        "MES routing command",
33	        "robot movement command",
34	        "height / length / column coordinate",
35	        "storage position",
36	        "material recipe",
37	        "pigment recipe",
38	        "manufacturing instruction"
39	      ];
40	
41	      function parseFP(s) {
42	        const parts = String(s || "").split("|").map(x => x.trim()).filter(Boolean);
43	        const raw = {};
44	        let fp = null;
45	
46	        for (const part of parts) {
47	          if (/^FP\d+$/.test(part)) {
48	            fp = part;
49	            raw.FP = part;
50	            continue;
51	          }
52	          const idx = part.indexOf("=");
53	          if (idx > -1) {
54	            const key = part.slice(0, idx).trim();
55	            const value = part.slice(idx + 1).trim();
56	            raw[key] = value;
57	          }
58	        }
59	
60	        const id = raw.ID || null;
61	        const anchor = raw.A || null;
62	        const st = raw.ST || null;
63	
64	        const errors = [];
65	        if (!id || !REF_RE.test(id)) errors.push("Missing or invalid primary Hxxx_Lxxx_Cxxx reference in ID.");
66	        if (anchor && !REF_RE.test(anchor)) errors.push("Invalid anchor Hxxx_Lxxx_Cxxx reference in A.");
67	        if (st && !(st in ALLOWED_OPERATORS)) errors.push("Unknown operator. Keep ST raw / unverified.");
68	
69	        return {
70	          block_type: "ARBE_FP_PROCESS_BLOCK",
71	          parse_status: errors.length ? "INVALID_OR_UNVERIFIED" : "VALID_REFERENCE_BLOCK",
72	          primary_reference: id,
73	          anchor_reference: anchor,
74	          operator: st ? {
75	            code: st,
76	            meaning: ALLOWED_OPERATORS[st] || null,
77	            status: ALLOWED_OPERATORS[st] ? "ALLOWED_OPERATOR" : "RAW_UNVERIFIED"
78	          } : null,
79	          raw_fields: raw,
80	          forbidden_interpretations: FORBIDDEN_INTERPRETATIONS,
81	          validation: {
82	            reference_pattern_valid: !!(id && REF_RE.test(id)),
83	            anchor_pattern_valid: !anchor || REF_RE.test(anchor),
84	            no_semantic_expansion: true,
85	            unknown_fields_remain_raw: true
86	          },
87	          errors: errors
88	        };
89	      }
90	
91	      return { parseFP };
92	    })();
93	
94	    (function(){
95	      const input = document.getElementById("arbe-fp-input");
96	      const output = document.getElementById("arbe-fp-output");
97	      const run = document.getElementById("arbe-fp-run");
98	      function render(){
99	        output.textContent = JSON.stringify(window.ARBE_FP_GUARDRAIL.parseFP(input.value), null, 2);
100	      }
101	      if (run && input && output) {
102	        run.addEventListener("click", render);
103	        render();
104	      }
105	    })();
106	    </script>
107	    <?php
108	    return ob_get_clean();
109	}
110	add_shortcode('arbe_fp_guardrail', 'arbe_fp_guardrail_shortcode');
